  "ai-prompt-flow": {
    id: "ai-prompt-flow",
    name: "AI Prompt via Azure OpenAI",
    description: "HTTP trigger \u2192 Azure OpenAI HTTP action \u2192 extract response \u2192 return via Response action",
    connectors: [],
    definition: {
      $schema: SCHEMA,
      contentVersion: "1.0.0.0",
      parameters: BASE_PARAMS,
      outputs: {},
      triggers: {
        manual: {
          type: "Request",
          kind: "Http",
          inputs: {
            schema: {
              type: "object",
              properties: {
                prompt: { type: "string" },
                context: { type: "string" }
              },
              required: ["prompt"]
            }
          }
        }
      },
      actions: {
        Call_Azure_OpenAI: {
          type: "Http",
          inputs: {
            method: "POST",
            uri: "REPLACE_WITH_AOAI_ENDPOINT",
            headers: {
              "Content-Type": "application/json",
              "api-key": "REPLACE_WITH_AOAI_KEY"
            },
            body: {
              model: "REPLACE_WITH_MODEL",
              messages: [
                {
                  role: "system",
                  content: "REPLACE_WITH_SYSTEM_PROMPT"
                },
                {
                  role: "user",
                  content: "@{triggerBody()?['prompt']}"
                }
              ]
            }
          },
          runAfter: {},
          runtimeConfiguration: {
            secureData: {
              properties: ["inputs"]
            }
          }
        },
        Extract_Response: {
          type: "Compose",
          inputs: "@body('Call_Azure_OpenAI')?['choices'][0]?['message']?['content']",
          runAfter: { Call_Azure_OpenAI: ["Succeeded"] }
        },
        Return_Response: {
          type: "Response",
          kind: "Http",
          inputs: {
            statusCode: 200,
            headers: { "Content-Type": "application/json" },
            body: {
              result: "@outputs('Extract_Response')",
              prompt: "@triggerBody()?['prompt']"
            }
          },
          runAfter: { Extract_Response: ["Succeeded"] }
        }
      }
    }
  },
