  "dataverse-event-flow": {
    id: "dataverse-event-flow",
    name: "Dataverse Event Notification",
    description: "Dataverse row change trigger (add/modify/delete) \u2192 Compose change summary \u2192 Condition on change type \u2192 Send notification email",
    connectors: ["shared_commondataserviceforapps", "shared_office365"],
    definition: {
      $schema: SCHEMA,
      contentVersion: "1.0.0.0",
      parameters: BASE_PARAMS,
      outputs: {},
      triggers: {
        When_a_row_changes: {
          type: "OpenApiConnectionNotification",
          inputs: {
            host: {
              apiId: "/providers/Microsoft.PowerApps/apis/shared_commondataserviceforapps",
              operationId: "SubscribeWebhookTrigger",
              connectionName: "shared_commondataserviceforapps"
            },
            parameters: {
              subscriptionRequest: {
                entityname: "REPLACE_WITH_TABLE_NAME",
                scope: 4,
                message: 3
              }
            }
          }
        }
      },
      actions: {
        Compose_Change_Summary: {
          type: "Compose",
          inputs: "Change detected on @{triggerBody()?['name']} (ID: @{triggerBody()?['_record_id']})",
          runAfter: {}
        },
        Condition_Change_Type: {
          type: "If",
          expression: {
            and: [{ equals: ["@triggerBody()?['SdkMessage']", "Create"] }]
          },
          actions: {
            Send_New_Record_Email: {
              type: "OpenApiConnection",
              inputs: {
                host: {
                  apiId: "/providers/Microsoft.PowerApps/apis/shared_office365",
                  operationId: "SendEmailV2",
                  connectionName: "shared_office365"
                },
                parameters: {
                  "emailMessage/To": "REPLACE_WITH_RECIPIENT_EMAIL",
                  "emailMessage/Subject": "New Record Created",
                  "emailMessage/Body": "<p><strong>New record:</strong> @{outputs('Compose_Change_Summary')}</p>"
                }
              },
              runAfter: {}
            }
          },
          else: {
            actions: {
              Send_Update_Email: {
                type: "OpenApiConnection",
                inputs: {
                  host: {
                    apiId: "/providers/Microsoft.PowerApps/apis/shared_office365",
                    operationId: "SendEmailV2",
                    connectionName: "shared_office365"
                  },
                  parameters: {
                    "emailMessage/To": "REPLACE_WITH_RECIPIENT_EMAIL",
                    "emailMessage/Subject": "Record Updated or Deleted",
                    "emailMessage/Body": "<p><strong>Change:</strong> @{outputs('Compose_Change_Summary')}</p>"
                  }
                },
                runAfter: {}
              }
            }
          },
          runAfter: { Compose_Change_Summary: ["Succeeded"] }
        }
      }
    }
  },
