  server2.tool("run_flow", "Trigger a manual flow run. Set wait=true to poll until completion. Uses the authenticated management path for Power Apps / Power Apps V2 (Direct-API) triggers, which reject unauthenticated calls. Request-family triggers keep using the SAS callback URL when a body is supplied so triggerBody() is populated. Set useCallbackUrl explicitly to override.", { env: external_exports.string().optional().describe("Environment ID"), flow: external_exports.string().describe("Flow ID"), body: jsonRecord.optional().describe("Trigger body JSON. For Power Apps V2 triggers, pass the schema parameters as top-level keys."), triggerName: external_exports.string().optional().describe("Trigger to invoke. Defaults to the flow's first trigger."), useCallbackUrl: external_exports.boolean().optional().describe("Force (true) or forbid (false) the unauthenticated SAS callback path. Ignored for Power Apps / Power Apps V2 triggers."), wait: external_exports.boolean().optional().describe("Wait for completion (default false)"), timeout: external_exports.number().optional().describe("Wait timeout seconds (default 60)") }, { readOnlyHint: false, title: "Run Flow" }, async ({ env, flow, body, triggerName, useCallbackUrl, wait, timeout }, extra) => {
    try {
      const envId = ctx.resolveEnv(env);
      const c = ctx.getClient();
      if (wait) {
        const prog = progress(extra);
        await prog.send(0, 100, `Triggering flow ${flow}\u2026`);
        let elapsed = 0;
        const totalSec = timeout ?? 60;
        const hb = prog.enabled ? setInterval(() => {
          elapsed += 2;
          void prog.send(Math.min(99, Math.floor(elapsed / totalSec * 100)), 100, `Polling run status\u2026 (${elapsed}s / ${totalSec}s)`);
        }, 2e3) : null;
        try {
          const triggerWallClock = Date.now() - 5e3;
          const triggerResult = await c.triggerFlowRun(envId, flow, { body, triggerName, useCallbackUrl });
          const deadline = Date.now() + (timeout ? timeout * 1e3 : 6e4);
          let finalRun = null;
          while (Date.now() < deadline) {
            await new Promise((r2) => setTimeout(r2, 2e3));
            try {
              const runs = await c.getRunHistory(envId, flow, { top: 3 });
              const recent = (runs ?? []).find((r2) => new Date(r2.properties?.startTime ?? 0).getTime() > triggerWallClock);
              if (recent && recent.properties?.status !== "Running") {
                finalRun = recent;
                break;
              }
              if (recent)
                finalRun = recent;
            } catch {
            }
          }
          let actions = [];
          if (finalRun?.name) {
            try {
              const acts = await c.getRunActionDetails(envId, flow, finalRun.name);
              actions = (acts ?? []).map((a) => ({
                name: a.name,
                status: a.properties?.status,
                durationMs: a.properties?.startTime && a.properties?.endTime ? new Date(a.properties.endTime).getTime() - new Date(a.properties.startTime).getTime() : null,
                errorCode: a.properties?.error?.code
              }));
            } catch {
            }
          }
          const result = {
            triggered: true,
            triggerName: triggerResult.triggerName,
            triggerKind: triggerResult.triggerKind,
            invocationPath: triggerResult.path,
            runId: finalRun?.name,
            status: finalRun?.properties?.status ?? "Unknown",
            startTime: finalRun?.properties?.startTime,
            endTime: finalRun?.properties?.endTime,
            errorCode: finalRun?.properties?.error?.code,
            errorMessage: finalRun?.properties?.error?.message,
            actions
          };
          await prog.send(100, 100, `Run completed: status=${result.status}`);
          return safeResult(result);
        } finally {
          if (hb)
            clearInterval(hb);
        }
      }
      const r = await c.triggerFlowRun(envId, flow, { body, triggerName, useCallbackUrl });
      return safeResult(r);
    } catch (e) {
      return safeError(e);
    }
  });
