  server2.tool("smoke_test", "End-to-end connectivity test: create, run, verify, cleanup", { env: external_exports.string().optional().describe("Environment ID") }, { readOnlyHint: false, title: "Smoke Test" }, async ({ env }) => {
    const envId = ctx.resolveEnv(env);
    const c = ctx.getClient();
    const t0 = Date.now();
    const def = { $schema: "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#", contentVersion: "1.0.0.0", parameters: { $authentication: { defaultValue: {}, type: "SecureObject" }, $connections: { defaultValue: {}, type: "Object" } }, triggers: { manual: { type: "Request", kind: "Button", inputs: { schema: { type: "object", properties: {}, required: [] } } } }, actions: { Compose_Smoke: { type: "Compose", inputs: { smoke: "ok", ts: "@utcNow()" }, runAfter: {} } } };
    let fid;
    try {
      const f = await c.createFlow(envId, { properties: { displayName: `_smoke-test-${Date.now()}`, definition: def, state: "Started" } }, { allowDuplicate: true });
      fid = f.name;
      await c.runFlow(envId, fid, {});
      let st = "Running";
      const dl = Date.now() + 3e4;
      while (st === "Running" && Date.now() < dl) {
        await new Promise((r) => setTimeout(r, 2e3));
        const runs = await c.getRunHistory(envId, fid, { top: 1 });
        if (runs.length)
          st = runs[0].properties.status;
      }
      const el = ((Date.now() - t0) / 1e3).toFixed(1);
      await c.deleteFlow(envId, fid, { forceManaged: true, skipBackup: true });
      fid = void 0;
      return safeResult({ passed: st === "Succeeded", status: st, elapsed_seconds: parseFloat(el) });
    } catch (e) {
      const el = ((Date.now() - t0) / 1e3).toFixed(1);
      if (fid)
        try {
          await c.deleteFlow(envId, fid, { forceManaged: true, skipBackup: true });
        } catch {
        }
      return safeError(new Error(`Smoke test failed after ${el}s: ${e instanceof Error ? e.message : e}`));
    }
  });
