    const here = path6.dirname(fileURLToPath2(import.meta.url));
    const recipesDir = path6.resolve(here, "..", "..", "docs", "recipes");
    const safeSlug = String(slug).replace(/[^a-z0-9-]/gi, "");
    const file2 = path6.join(recipesDir, `${safeSlug}.md`);
