var config2 = loadConfig();
var auth = buildCompositeAuth({
  cloud: config2.cloud,
  cloudEndpoints: config2.cloudEndpoints
});
var server = await createMcpServer(auth, {
  config: config2,
  ...createTelemetryObserver({
    transport: "stdio",
    getClientInfo: () => server?.server?.getClientVersion?.()
  })
});
var transport = new StdioServerTransport();
await server.connect(transport);
var toolCount = countRegisteredTools(server);
console.error(`FlowAgent MCP server running on stdio (${toolCount} tools)`);
function countRegisteredTools(srv) {
  try {
    const internal = srv._registeredTools;
    if (internal && typeof internal === "object") {
      return Object.keys(internal).length;
    }
  } catch {
  }
  return 0;
}
